// Render translates markdown to HTML.
func Render(markdown string) string {
	// Emphasis is applied first so that __bold__ and _italic_ markers
	// are resolved regardless of where they appear in the document.
	markdown = replaceEmphasis(markdown)

	var b strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			b.WriteString("</li></ul>")
			inList = false
		}
		switch {
		case isListItem(line):
			if !inList {
				b.WriteString("<ul>")
				inList = true
			} else {
