package markdown

// Render translates markdown to HTML.
//
// The document is processed one line at a time. Each line is either a
// header (# Heading), a list item (* Item), or a paragraph. Emphasis
// markers (__bold__ and _italic_) are resolved before the lines are
// parsed so that they work inside any element.

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var html strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			html.WriteString("</ul>")
			inList = false
		}
		switch level := headerLevel(line); {
		case isListItem(line):
			if !inList {
				html.WriteString("<ul>")
				inList = true
			}
			html.WriteString("<li>" + strings.TrimPrefix(line, "* ") + "</li>")
		case level > 0:
			html.WriteString(fmt.Sprintf("<h%d>%s</h%d>", level, strings.TrimPrefix(line, strings.Repeat("#", level)), level))
		default:
			html.WriteString("<p>" + line + "</p>")
		}
	}
	if inList {
		html.WriteString("</ul>")
	}
	return html.String()
}
```

